'use strict';

/**
 * Latency harness. Dependency-free, so the numbers in the README can be
 * regenerated by anyone:
 *
 *   npm run bench
 *   BENCH_REQUESTS=20000 BENCH_CONCURRENCY=100 npm run bench
 *
 * It measures three identical servers - unlimited, MemoryStore, RedisStore -
 * and reports the added latency per configuration. The Redis run is skipped
 * automatically when no Redis is reachable.
 *
 * Caveats worth stating next to any result:
 *   - Loopback traffic, and the load generator shares this process's event
 *     loop with the server. That is why concurrency defaults to 1: it is the
 *     only setting where the numbers isolate per-request cost rather than
 *     queueing. Raising it measures throughput, and the latency deltas become
 *     noise (they can even come out negative).
 *   - The handler does no work, so the limiter's share of a real request is
 *     proportionally much smaller than it looks here.
 *   - Limits are set high enough that nothing is rejected; a rejected request
 *     is cheaper, so mixing them in would flatter the numbers.
 */

const express = require('express');
const net = require('node:net');

const rateLimiter = require('../src/middleware/rateLimiter');
const MemoryStore = require('../src/storage/memoryStore');
const RedisStore = require('../src/storage/redisStore');

const TOTAL_REQUESTS = Number(process.env.BENCH_REQUESTS ?? 3000);
const CONCURRENCY = Number(process.env.BENCH_CONCURRENCY ?? 1);
const REDIS_URL = process.env.TEST_REDIS_URL ?? 'redis://127.0.0.1:6379';

function probe(host, port, timeoutMs = 300) {
  return new Promise((resolve) => {
    const socket = net.connect({ host, port });
    const done = (r) => {
      socket.destroy();
      resolve(r);
    };
    socket.setTimeout(timeoutMs, () => done(false));
    socket.once('connect', () => done(true));
    socket.once('error', () => done(false));
  });
}

async function listen(middleware) {
  const app = express();
  if (middleware) app.use(middleware);
  app.get('/', (req, res) => res.json({ ok: true }));

  const server = await new Promise((resolve) => {
    const s = app.listen(0, '127.0.0.1', () => resolve(s));
  });
  return { server, base: `http://127.0.0.1:${server.address().port}/` };
}

function percentile(sorted, p) {
  if (sorted.length === 0) return 0;
  const index = Math.min(sorted.length - 1, Math.ceil((p / 100) * sorted.length) - 1);
  return sorted[index];
}

async function measure(label, middleware) {
  const { server, base } = await listen(middleware);
  const latencies = [];
  let rejected = 0;
  let issued = 0;

  // Warm up: first-request costs (script load, connection setup) are real but
  // would otherwise dominate a short run.
  for (let i = 0; i < Math.min(50, TOTAL_REQUESTS); i += 1) await fetch(base);

  const startedAt = process.hrtime.bigint();
  await Promise.all(
    Array.from({ length: CONCURRENCY }, async () => {
      while (issued < TOTAL_REQUESTS) {
        issued += 1;
        const t0 = process.hrtime.bigint();
        const res = await fetch(base);
        latencies.push(Number(process.hrtime.bigint() - t0) / 1e6);
        if (res.status === 429) rejected += 1;
      }
    })
  );
  const wallMs = Number(process.hrtime.bigint() - startedAt) / 1e6;

  server.closeAllConnections?.();
  await new Promise((resolve) => server.close(resolve));
  latencies.sort((a, b) => a - b);

  return {
    label,
    requests: latencies.length,
    rejected,
    rps: Math.round((latencies.length / wallMs) * 1000),
    p50: percentile(latencies, 50),
    p95: percentile(latencies, 95),
    p99: percentile(latencies, 99)
  };
}

async function main() {
  console.log(
    `benchmark: ${TOTAL_REQUESTS} requests, concurrency ${CONCURRENCY}, node ${process.version}\n`
  );

  const rows = [];
  rows.push(await measure('no rate limiting', null));

  const memoryStore = new MemoryStore({ autoCleanup: false });
  rows.push(
    await measure(
      'MemoryStore',
      rateLimiter({ requestsPerMinute: 6_000_000, scope: 'bench-mem', store: memoryStore })
    )
  );
  await memoryStore.close();

  const { hostname, port } = new URL(REDIS_URL);
  if (await probe(hostname, Number(port || 6379))) {
    const redisStore = new RedisStore({ url: REDIS_URL, keyPrefix: 'ratelimit-bench:' });
    await redisStore.connect();
    rows.push(
      await measure(
        'RedisStore',
        rateLimiter({ requestsPerMinute: 6_000_000, scope: 'bench-redis', store: redisStore })
      )
    );
    await redisStore.resetAll();
    await redisStore.close();
  } else {
    console.log(`(skipping RedisStore: nothing listening at ${REDIS_URL})\n`);
  }

  const baseline = rows[0].p50;
  const pad = (s, n) => String(s).padEnd(n);
  console.log(
    `${pad('configuration', 20)}${pad('rps', 10)}${pad('p50 ms', 10)}${pad('p95 ms', 10)}${pad('p99 ms', 10)}added p50`
  );
  for (const row of rows) {
    console.log(
      pad(row.label, 20) +
        pad(row.rps, 10) +
        pad(row.p50.toFixed(2), 10) +
        pad(row.p95.toFixed(2), 10) +
        pad(row.p99.toFixed(2), 10) +
        `+${(row.p50 - baseline).toFixed(2)} ms`
    );
    if (row.rejected > 0) console.log(`  warning: ${row.rejected} requests were rejected`);
  }

  if (CONCURRENCY > 1) {
    console.log(
      `\nnote: concurrency is ${CONCURRENCY}, so the "added p50" column is dominated by ` +
        'queueing in this process. Use concurrency 1 to compare per-request cost.'
    );
  }
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
